-- U2: agregados explícitos. No transforma ni infiere el significado de registros históricos.
CREATE TABLE institution_sol(id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL UNIQUE,destination_id VARCHAR(36) NOT NULL,state VARCHAR(20) NOT NULL,revision BIGINT NOT NULL,classification_text VARCHAR(2000) NOT NULL,domicile_region VARCHAR(40),created_by VARCHAR(64) NOT NULL,created_ms BIGINT NOT NULL,FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(destination_id,communication_id) REFERENCES core_destination(id,communication_id),FOREIGN KEY(created_by) REFERENCES core_actor(id),FOREIGN KEY(domicile_region) REFERENCES org_region(id),CHECK(state IN ('PENDIENTE','ASUMIDA')));
CREATE TABLE institution_req(requirement_id VARCHAR(36) PRIMARY KEY,sol_id VARCHAR(36) UNIQUE,principal_destination VARCHAR(36) NOT NULL,unit_code VARCHAR(8) NOT NULL,site_id VARCHAR(40) NOT NULL,area_id VARCHAR(64),attention_actor VARCHAR(64) NOT NULL,complexity VARCHAR(8),authority_revision BIGINT NOT NULL,origin_code VARCHAR(24) NOT NULL,FOREIGN KEY(requirement_id) REFERENCES core_requirement(id),FOREIGN KEY(sol_id) REFERENCES institution_sol(id),FOREIGN KEY(principal_destination) REFERENCES core_destination(id),FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),FOREIGN KEY(area_id) REFERENCES institution_area(id),FOREIGN KEY(attention_actor) REFERENCES core_actor(id),FOREIGN KEY(authority_revision) REFERENCES authority_batch(revision),CHECK(complexity IS NULL OR complexity IN ('BAJA','MEDIANA','ALTA')),CHECK(origin_code IN ('PRIMERA_ATENCION','ASUNCION_SOL')));
CREATE TABLE institution_case(case_id VARCHAR(36) PRIMARY KEY,objective_text VARCHAR(2000) NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id));
CREATE TABLE institution_collaboration(id VARCHAR(36) PRIMARY KEY,requirement_id VARCHAR(36) NOT NULL,unit_code VARCHAR(8) NOT NULL,site_id VARCHAR(40) NOT NULL,area_id VARCHAR(64),objective_text VARCHAR(2000) NOT NULL,state VARCHAR(12) NOT NULL,revision BIGINT NOT NULL,requested_by VARCHAR(64) NOT NULL,created_ms BIGINT NOT NULL,case_id VARCHAR(36) UNIQUE,FOREIGN KEY(requirement_id) REFERENCES institution_req(requirement_id),FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),FOREIGN KEY(area_id) REFERENCES institution_area(id),FOREIGN KEY(requested_by) REFERENCES core_actor(id),FOREIGN KEY(case_id) REFERENCES core_case(id),CHECK(state IN ('PENDIENTE','ACEPTADA','RECHAZADA','RETIRADA')),CHECK((state='ACEPTADA' AND case_id IS NOT NULL) OR (state<>'ACEPTADA' AND case_id IS NULL)));
CREATE TABLE institution_flow_history(seq BIGINT AUTO_INCREMENT PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,resource_id VARCHAR(36) NOT NULL,resource_kind VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,action_code VARCHAR(40) NOT NULL,reason_text VARCHAR(12000) NOT NULL,snapshot_doc LONGTEXT NOT NULL,FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE INDEX ix_u2_history ON institution_flow_history(resource_id,seq);
CREATE INDEX ix_u2_collaboration ON institution_collaboration(requirement_id,state);
-- La evidencia dinámica se distingue del registro firmado 1.3; no se reinterpreta su firma.
ALTER TABLE communication_pertinence_history ADD COLUMN principal_origin VARCHAR(24) NOT NULL DEFAULT 'REGISTRO_1_3';
